const identifierPattern = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;

const SAFE_OUTPUT_KEYS = new Set([
  "status",
  "result",
  "mode",
  "provider",
  "model",
  "action",
  "decision",
  "classification",
  "route",
  "eligible",
