export type ShippingMode = "DEMO_SANDBOX" | "SHIPBUBBLE_TEST";
export type ShippingErrorClassification =
  | "TRANSIENT_READ"
  | "PERMANENT"
  | "AMBIGUOUS_WRITE";

export interface QuoteRequest {
  caseId: string;
  orderId: string;
  route: "PREFERRED" | "ALTERNATIVE";
  currency: "NGN";
  origin: {
    area: string;
